"import csv

from openpyxl import Workbook

INPUT_FILE = "eng_flag_03.csv"
OUTPUT_FILE = "output.xlsx"

CHANNELS = ["alt_ft", "ias_kt", "load_g"]
LIMITS = {
    "alt_ft": (9000.0, 18000.0),
    "ias_kt": (135.0, 210.0),
    "load_g": (1.0, 2.2),
}
DATA_HEADER = ["time", "alt_ft", "ias_kt", "load_g", "status_alt", "status_ias", "status_load"]
STATS_HEADER = ["channel", "min", "max", "mean"]


def parse_optional_float(text):
    """Return float for non-empty text, else None (empty)."""
    if text is None:
        return None
    text = text.strip()
    if text == "":
        return None
    return float(text)


def classify(value, lo, hi):
    """MISSING if empty; OVER if outside inclusive [lo, hi]; OK otherwise."""
    if value is None:
        return "MISSING"
    if value < lo or value > hi:
        return "OVER"
    return "OK"


def main():
    # 1. Read source CSV
    with open(INPUT_FILE, newline="", encoding="utf-8-sig") as fh:
        reader = csv.DictReader(fh)
        records = [dict(row) for row in reader]

    wb = Workbook()

    # ---- Sheet DATA ----
    ws = wb.active
    ws.title = "DATA"
    ws.append(DATA_HEADER)

    channel_values = {ch: [] for ch in CHANNELS}

    for rec in records:
        # time column copied unchanged (numeric if it parses as a number)
        time_raw = (rec.get("time") or "").strip()
        time_val = time_raw
        if time_val != "":
            try:
                time_val = float(time_raw)
            except ValueError:
                time_val = time_raw

        row_values = [time_val]
        for ch in CHANNELS:
            val = parse_optional_float(rec.get(ch))
            row_values.append(val)
            if val is not None:
                channel_values[ch].append(val)

        status_values = [
            classify(row_values[i + 1], LIMITS[ch][0], LIMITS[ch][1])
            for i, ch in enumerate(CHANNELS)
        ]

        excel_row = ws.max_row + 1
        for col_idx, value in enumerate(row_values + status_values, start=1):
            if value is None:
                continue  # leave the cell truly empty (no 0, no blank string)
            ws.cell(row=excel_row, column=col_idx, value=value)

    # ---- Sheet STATS ----
    ws_stats = wb.create_sheet("STATS")
    ws_stats.append(STATS_HEADER)
    for ch in sorted(CHANNELS):
        vals = channel_values[ch]
        if vals:
            mn = round(min(vals), 3)
            mx = round(max(vals), 3)
            mean = round(sum(vals) / len(vals), 3)
            ws_stats.append([ch, mn, mx, mean])
        else:
            ws_stats.append([ch])

    wb.save(OUTPUT_FILE)


if __name__ == "__main__":
    main()"
